190	    ```csharp
191	    using System.Security.Cryptography;
192	
193	    namespace seed_a_backend.Api.Services;
194	
195	    public class ReferenzGenerator : IReferenzGenerator
196	    {
197	        private const string Alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"; // Crockford Base32, ohne I L O U
198	        private const int Laenge = 8;
199	
200	        public string Naechste()
201	        {
202	            Span<char> buffer = stackalloc char[Laenge];
203	            for (var i = 0; i < Laenge; i++)
204	            {
205	                buffer[i] = Alphabet[RandomNumberGenerator.GetInt32(Alphabet.Length)];
