152	  protected onSitzplanKeydown(event: KeyboardEvent): void {
153	    const plan = this.sitzplan();
154	    const aktuell = this.fokussiertePosition();
155	    if (!plan || !aktuell) return;
156	
157	    switch (event.key) {
158	      case 'ArrowRight':
159	        event.preventDefault();
160	        this.bewegeHorizontal(plan, aktuell, 1);
161	        break;
162	      case 'ArrowLeft':
163	        event.preventDefault();
164	        this.bewegeHorizontal(plan, aktuell, -1);
165	        break;
166	      case 'ArrowDown':
167	        event.preventDefault();
168	        this.bewegeVertikal(plan, aktuell, 1);
169	        break;
170	      case 'ArrowUp':
171	        event.preventDefault();
172	        this.bewegeVertikal(plan, aktuell, -1);
173	        break;
174	      case ' ':
175	      case 'Enter':
176	        event.preventDefault();
177	        this.aktiviereFokussiertePosition(plan, aktuell);
178	        break;
179	    }
180	  }
181	
182	  private aktiviereFokussiertePosition(plan: Sitzplan, aktuell: Position): void {
183	    const reihe = plan.reihen.find((r) => r.reihe === aktuell.reihe);
184	    const position = reihe?.positionen.find((p) => p.spalte === aktuell.spalte);
185	    if (!position || position.status === 'Belegt' || !position.code) return;
186	    this.auswahlUmschalten(position.code);
187	  }
188	
189	  private bewegeHorizontal(plan: Sitzplan, aktuell: Position, richtung: 1 | -1): void {
190	    const reihe = plan.reihen.find((r) => r.reihe === aktuell.reihe);
191	    if (!reihe) return;
192	    let spalte = aktuell.spalte + richtung;
193	    while (spalte >= 1 && spalte <= reihe.positionen.length) {
194	      const position = reihe.positionen.find((p) => p.spalte === spalte);
195	      if (position?.typ === 'Sitzplatz') {
196	        this.setzeFokus({ reihe: aktuell.reihe, spalte });
197	        return;
198	      }
199	      spalte += richtung;
200	    }
201	  }
202	
203	  private bewegeVertikal(plan: Sitzplan, aktuell: Position, richtung: 1 | -1): void {
204	    const rowIndex = plan.reihen.findIndex((r) => r.reihe === aktuell.reihe);
205	    const naechsterIndex = rowIndex + richtung;
206	    if (naechsterIndex < 0 || naechsterIndex >= plan.reihen.length) return;
207	    const naechsteReihe = plan.reihen[naechsterIndex];
208	    const position = naechsteReihe.positionen.find((p) => p.spalte === aktuell.spalte);
209	    if (!position) return;
210	    this.setzeFokus({ reihe: naechsteReihe.reihe, spalte: aktuell.spalte });
211	  }
212	
213	  private setzeFokus(position: Position): void {
214	    this.fokussiertePosition.set(position);
215	    const code = `${position.reihe}${position.spalte}`;
216	    (
217	      this.sitzplanRef()?.nativeElement.querySelector(`[data-code="${code}"]`) as HTMLElement | null
218	    )?.focus();
219	  }
220	
221	  private ersteSitzplatzPosition(plan: Sitzplan): Position | null {
222	    for (const reihe of plan.reihen) {
223	      const position = reihe.positionen.find((p: SitzplanPosition) => p.typ === 'Sitzplatz');
224	      if (position) return { reihe: reihe.reihe, spalte: position.spalte };
225	    }
226	    return null;
227	  }
228	}
